cd /app && cat > /tmp/pt2/diag_test.go <<'EOF'
package main

import (
	"context"
	"fmt"
	"testing"

	"github.com/prometheus/prometheus/model/labels"
	"github.com/prometheus/prometheus/promql/promqltest"
)

func TestDiag(t *testing.T) {
	input := `clear
load 5m
	typed_vals{val="+Inf"} 1
	typed_vals{val="-Inf"} 1
	typed_vals{val="foo"} 1
`
	storage := promqltest.LoadedStorage(t, input)
	defer storage.Close()
	q, err := storage.Querier(0, 1000)
	if err != nil {
		t.Fatal(err)
	}
	defer q.Close()
	ss := q.Select(context.Background(), false, nil, labels.MustNewMatcher(labels.MatchRegexp, "__name__", "typed_vals"))
	for ss.Next() {
		fmt.Println("series:", ss.At().Labels().String())
	}
	if err := ss.Err(); err != nil {
		t.Fatal(err)
	}
}
EOF
cd /app && timeout 90 go test -run TestDiag /tmp/pt2/diag_test.go 2>&1 | tail -30

